$ProbeRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
$env:PYTHONPATH = "$ProbeRoot/bootstrap;$ProbeRoot/perseus"
$env:UV_CACHE_DIR = "$ProbeRoot/.uv-cache"
$env:TEMP = "$ProbeRoot/tmp"
$env:TMP = $env:TEMP
$env:UV_PYTHON_DOWNLOADS = 'never'
$env:PYTHONDONTWRITEBYTECODE = '1'
$env:HF_HOME = "$ProbeRoot/.hf-cache"
$env:TORCH_HOME = "$ProbeRoot/.torch-cache"
$env:XDG_CACHE_HOME = "$ProbeRoot/.cache"
$env:ACCELERATE_MIXED_PRECISION = 'bf16'
$env:POLARS_MAX_THREADS = '4'
$env:HTTP_PROXY = ''
$env:HTTPS_PROXY = ''
$env:ALL_PROXY = ''
$env:NO_PROXY = '*'
$env:INTERNAL_STORAGE_EVENT_HUB = "$ProbeRoot/probe/event_hub"
$ProbePython = "$ProbeRoot/perseus/.venv/Scripts/python.exe"
